79	  if (config_.use_gpu) {
80	    place_ = paddle::platform::CUDAPlace(config_.device);
81	  } else {
82	    place_ = paddle::platform::CPUPlace();
83	  }
84	  if (parent_scope) {
85	    scope_ = parent_scope;
86	    sub_scope_ = &(parent_scope->NewScope());
87	    PADDLE_ENFORCE_NOT_NULL(sub_scope_, "create sub scope fail");
88	  } else {
